import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Per-User Settings — Glacier","description":"Glacier features your users control themselves — dark/light, privacy mode, sounds, the editor file tree and Ctrl+K search.","frontmatter":{"title":"Per-User Settings — Glacier","description":"Glacier features your users control themselves — dark/light, privacy mode, sounds, the editor file tree and Ctrl+K search."},"headers":[],"relativePath":"glacier/user-guide/user-settings.md","filePath":"glacier/user-guide/user-settings.md","lastUpdated":1785230800000}'),o={name:"glacier/user-guide/user-settings.md"};function i(l,e,n,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="per-user-settings" tabindex="-1">Per-User Settings <a class="header-anchor" href="#per-user-settings" aria-label="Permalink to &quot;Per-User Settings&quot;">​</a></h1><p>Glacier is configured panel-wide by admins, but a handful of comforts belong to each user. These live in the <strong>account menu</strong>, the <strong>account page Panel settings card</strong>, or right where they&#39;re used — stored per browser (localStorage), never in the panel database, so one user&#39;s choices never leak into another&#39;s session.</p><h2 id="dark-light-toggle" tabindex="-1">Dark / light toggle <a class="header-anchor" href="#dark-light-toggle" aria-label="Permalink to &quot;Dark / light toggle&quot;">​</a></h2><p>When <code>mode_toggle</code> is on (default), the account menu carries a dark/light switch. With <code>mode: auto</code> the panel follows the OS until the user overrides it manually.</p><h2 id="privacy-mode" tabindex="-1">Privacy mode <a class="header-anchor" href="#privacy-mode" aria-label="Permalink to &quot;Privacy mode&quot;">​</a></h2><p>One toggle blurs every sensitive identifier panel-wide — server IPs and addresses, the console address chip, account email, API fields — until hovered. Built for streaming and screen-shares; the admin can pre-blur just the server address globally with <code>blur_server_address</code>.</p><h2 id="interface-sounds" tabindex="-1">Interface sounds <a class="header-anchor" href="#interface-sounds" aria-label="Permalink to &quot;Interface sounds&quot;">​</a></h2><p>Subtle UI sounds (toggles, reveals), off by default (<code>sounds_default: 0</code>). Each user flips them on from the account menu; the admin default only applies to users who never chose.</p><h2 id="editor-file-tree" tabindex="-1">Editor file tree <a class="header-anchor" href="#editor-file-tree" aria-label="Permalink to &quot;Editor file tree&quot;">​</a></h2><p>A VS Code-style explorer on the file editor: directory tree with Glacier&#39;s file-type icons, the current file highlighted, a dirty marker for unsaved changes, and a drag-resize sash (width remembered per browser). Users enable it from the account page&#39;s <strong>Panel settings</strong> card.</p><h2 id="ctrl-k-search-palette" tabindex="-1">Ctrl+K search palette <a class="header-anchor" href="#ctrl-k-search-palette" aria-label="Permalink to &quot;Ctrl+K search palette&quot;">​</a></h2><p>With <code>shortcuts</code> on (default), <code>Ctrl+K</code> (or the topbar search pill) opens a fuzzy palette across <strong>servers and pages</strong>:</p><ul><li>Arrow keys navigate, <code>Enter</code> opens, <code>Esc</code> closes.</li><li>Results land on the right server-scoped route (e.g. <code>/server/&lt;id&gt;/files</code>, not a bare <code>/files</code>).</li><li>No result is pre-highlighted — the list only reacts to actual input.</li></ul><h2 id="account-page-cards" tabindex="-1">Account page cards <a class="header-anchor" href="#account-page-cards" aria-label="Permalink to &quot;Account page cards&quot;">​</a></h2><p>The account page gains two Glacier cards:</p><ul><li><strong>Profile</strong> — view-first identity; email becomes editable only when the admin enables <code>account_edit_email</code>.</li><li><strong>Panel settings</strong> — the per-user toggles above, in one place.</li></ul><div class="info custom-block"><p class="custom-block-title">Why localStorage?</p><p>Per-user UI prefs in localStorage survive re-logins on the same browser, apply instantly (no save round-trip), and keep the panel&#39;s settings store strictly admin-owned. Switching browsers or devices resets them to the admin defaults — by design.</p></div>',17)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
